<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, takeStepUpToken } from '../api'
import type { AdminUser, Merchant } from '../types'
const users = ref<AdminUser[]>([]); const merchants = ref<Merchant[]>([]); const message = ref(''); const error = ref('')
const form = ref({ username: '', password: 'Temporary@123', displayName: '', email: '', mobile: '', roleCodes: ['PAYMENT_OPERATOR'], requireMfa: true, requirePasswordChange: true })
const grant = ref({ userId: 0, merchantId: 0, permissionScope: 'OPERATE' })
async function load() { users.value = await api('/api/admin/users'); merchants.value = await api('/api/admin/merchants') }
onMounted(load)
async function create() { const token = takeStepUpToken(); if (!token) { error.value = '请先在安全中心获取一次性 Step-up 令牌。'; return } try { await api('/api/admin/users', { method: 'POST', headers: { 'X-Step-Up-Token': token }, body: JSON.stringify(form.value) }); message.value = '账号创建成功，临时密码需通过安全渠道交付。'; await load() } catch(e) { error.value = e instanceof Error ? e.message : '创建失败' } }
async function grantAccess() { const token = takeStepUpToken(); if (!token) { error.value = '请先在安全中心获取一次性 Step-up 令牌。'; return } try { await api(`/api/admin/users/${grant.value.userId}/merchants`, { method: 'POST', headers: { 'X-Step-Up-Token': token }, body: JSON.stringify(grant.value) }); message.value = '商户数据权限已更新。' } catch(e) { error.value = e instanceof Error ? e.message : '授权失败' } }
</script>
<template><div class="page-title"><div><span class="eyebrow">IDENTITY & ACCESS</span><h1>后台账号与商户权限</h1><p>认证身份、平台角色和商户数据范围分层管理。</p></div></div><div v-if="message" class="notice success">{{ message }}</div><div v-if="error" class="notice error">{{ error }}</div><div class="content-grid"><form class="card" @submit.prevent="create"><span class="eyebrow">CREATE IDENTITY</span><h3>创建后台账号</h3><label>用户名<input v-model="form.username" required /></label><label>显示名称<input v-model="form.displayName" required /></label><label>邮箱<input v-model="form.email" type="email" required /></label><label>临时密码<input v-model="form.password" type="password" minlength="12" required /></label><label>平台角色<select v-model="form.roleCodes[0]"><option>PAYMENT_ADMIN</option><option>PAYMENT_OPERATOR</option><option>PAYMENT_AUDITOR</option></select></label><label class="checkbox"><input v-model="form.requireMfa" type="checkbox" /> 要求绑定 MFA</label><label class="checkbox"><input v-model="form.requirePasswordChange" type="checkbox" /> 首次登录修改密码</label><button class="primary full">创建安全身份</button></form><article class="card span-2"><div class="card-head"><div><span class="eyebrow">DIRECTORY</span><h3>账号目录</h3></div></div><table><thead><tr><th>账号</th><th>角色</th><th>MFA</th><th>状态</th></tr></thead><tbody><tr v-for="item in users" :key="item.id"><td><b>{{ item.displayName }}</b><small>{{ item.username }} · {{ item.email }}</small></td><td>{{ item.roles.join(', ') }}</td><td>{{ item.mfaEnabled ? '已启用' : item.mfaRequired ? '待绑定' : '未要求' }}</td><td><span :class="['badge', item.accountLocked ? 'failed' : 'success']">{{ item.accountLocked ? 'LOCKED' : item.status }}</span></td></tr></tbody></table><form class="grant-form" @submit.prevent="grantAccess"><h4>分配商户数据范围</h4><select v-model.number="grant.userId" required><option :value="0" disabled>选择账号</option><option v-for="u in users" :value="u.id">{{ u.displayName }}</option></select><select v-model.number="grant.merchantId" required><option :value="0" disabled>选择商户</option><option v-for="m in merchants" :value="m.id">{{ m.displayName }}</option></select><select v-model="grant.permissionScope"><option>READ_ONLY</option><option>OPERATE</option><option>REFUND</option><option>AUDIT</option><option>ADMIN</option></select><button class="secondary">保存权限</button></form></article></div></template>
